// Assets: the app's own icons (Lucide, generated by scripts/lucide-icons.mjs,
// plus the Filo mark) and Filo's animal avatars (the phone's pictures, as
// `avatars/<id>.webp`) and the agents' pictures (`workers/<name>.png`) first,
// then gpui-component's bundled icons.

use std::borrow::Cow;

use anyhow::Result;
use gpui::{AssetSource, SharedString};
use rust_embed::RustEmbed;

/// The icons gpui-component's own assets already have (check, chevron-down, …) aren't here: `Assets` falls back to
/// them. The note editor's toolbar icons (bold, heading, …) are inlined in assets/web/note-editor.js, so they're left out.
#[derive(RustEmbed)]
#[folder = "assets"]
#[include = "icons/*.svg"]
#[include = "fonts/*.ttf"]
#[include = "images/*.png"]
#[exclude = "icons/bold.svg"]
#[exclude = "icons/heading.svg"]
#[exclude = "icons/italic.svg"]
#[exclude = "icons/list-ordered.svg"]
#[exclude = "icons/strikethrough.svg"]
pub struct Embedded;

#[derive(RustEmbed)]
#[folder = "assets/images/filo/avatars"]
#[include = "*.webp"]
struct Avatars;

/// The agents Filo hands work to (Sunny, Indi, …): the phone's pictures, as `workers/<name>.png`.
#[derive(RustEmbed)]
#[folder = "assets/images/filo/workers"]
#[include = "*.png"]
struct Workers;

/// Filo's animals in the other colours (avatar_colors.rs, made by scripts/avatar-colors.sh), as
/// `avatar-colors/<color>/<id>.webp`.
#[derive(RustEmbed)]
#[folder = "assets/images/filo/avatar-colors"]
#[include = "*/*.webp"]
struct AvatarColors;

/// An animal's picture in a colour other than blue (`teal`, `fox-idle`), WebP.
pub fn avatar_color_bytes(color: &str, id: &str) -> Option<Cow<'static, [u8]>> {
    AvatarColors::get(&format!("{color}/{id}.webp")).map(|file| file.data)
}

/// An animal avatar's picture (`bear-waving`), WebP.
pub fn avatar_bytes(id: &str) -> Option<Cow<'static, [u8]>> {
    Avatars::get(&format!("{id}.webp")).map(|file| file.data)
}

pub struct Assets;

impl AssetSource for Assets {
    fn load(&self, path: &str) -> Result<Option<Cow<'static, [u8]>>> {
        if let Some(file) = Embedded::get(path) {
            return Ok(Some(file.data));
        }
        if let Some(id) = path.strip_prefix("avatars/").and_then(|name| name.strip_suffix(".webp")) {
            return Ok(avatar_bytes(id));
        }
        if let Some(rest) = path.strip_prefix("avatar-colors/") {
            return Ok(AvatarColors::get(rest).map(|file| file.data));
        }
        if let Some(name) = path.strip_prefix("workers/") {
            return Ok(Workers::get(name).map(|file| file.data));
        }
        gpui_component_assets::Assets.load(path)
    }

    fn list(&self, path: &str) -> Result<Vec<SharedString>> {
        let mut items: Vec<SharedString> =
            Embedded::iter().filter(|name| name.starts_with(path)).map(|name| name.to_string().into()).collect();
        items.extend(gpui_component_assets::Assets.list(path)?);
        Ok(items)
    }
}

pub fn fonts() -> Vec<Cow<'static, [u8]>> {
    Embedded::iter()
        .filter(|name| name.starts_with("fonts/"))
        .filter_map(|name| Embedded::get(&name).map(|file| file.data))
        .collect()
}
